pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 m, uint256 d, uint256 am) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(d < m);
        vm.assume(am <= d);
        try c.SetMinSum(m) {} catch { return; }
        try c.Deposit{value: d}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        uint myEthBefore = address(this).balance;
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.balances(address(this)) == balBefore && address(c).balance == ethBefore && address(this).balance == myEthBefore);
    }

    function testFuzz_run(uint256 m, uint256 d, uint256 am) public {
        _run(m, d, am);
    }

    receive() external payable {}
}
